import java.util.*;
import java.io.*;

public class Main {
    static int n, total, answer;
    static long[] sumArr = new long[15];
    static List<Long>[] vectors = new ArrayList[15];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        for (int i = 0; i <= 14; i++) {
            vectors[i] = new ArrayList<>();
        }
        dfs1(0, 0);
        for (int i = 0; i <= 7; i++) {
            Collections.sort(vectors[i]);
        }
        total = 0;
        for (int i = 1; i <= 9; i++) {
            dfs2(i);
        }
        System.out.println(answer);
    }

    static void dfs1(int level, long num) {
        if (level == 7) return;
        total++;
        long back = ((total - num) % 998244353 + 998244353) % 998244353;
        vectors[level].add(back);
        sumArr[level] = (sumArr[level] + back) % 1000000007;
        for (int i = 0; i <= 9; i++) {
            dfs1(level + 1, num * 10 + i);
        }
    }

    static void dfs2(long x) {
        if (x > n) return;
        if (x * 1000000 + 999999 <= n && x * 10 * 1000000 > n) {
            long current = total;
            for (int i = 0, mul = 1; i <= 6; i++, mul *= 10) {
                int sizeVec = vectors[i].size();
                long diffVal = ((current - x * mul) % 998244353 + 998244353) % 998244353;
                int pos = lowerBound(vectors[i], 1000000000 - diffVal);
                answer = (int)((answer + diffVal * sizeVec + sumArr[i]) % 1000000007);
                long subtractVal = (998244353L * (sizeVec - pos)) % 1000000007;
                answer = (int)((answer - subtractVal + 1000000007) % 1000000007);
                total += sizeVec;
            }
            return;
        }
        total++;
        long temp = ((total - x) % 998244353 + 998244353) % 998244353;
        answer = (int)((answer + temp) % 1000000007);
        for (int i = 0; i <= 9; i++) {
            dfs2(x * 10 + i);
        }
    }

    static int lowerBound(List<Long> list, long key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
